import type { JobRow } from './db.ts';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The public job representation returned by every endpoint that returns a job. */
export interface PublicJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A validated submission with defaults applied. */
export interface JobSubmission {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export type ValidationResult = { ok: true; value: JobSubmission } | { ok: false; fields: FieldError[] };

export const DEFAULT_STEPS = 5;
export const DEFAULT_FAIL_ATTEMPTS = 0;
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

const hasOwn = (obj: object, key: string): boolean => Object.prototype.hasOwnProperty.call(obj, key);

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function integerField(obj: Record<string, unknown>, name: string, def: number, min: number, max: number, fields: FieldError[]): number {
  if (!hasOwn(obj, name)) return def;
  const v = obj[name];
  if (typeof v !== 'number' || !Number.isInteger(v)) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
    return def;
  }
  if (v < min || v > max) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
    return def;
  }
  return v;
}

/** Parses a raw request body as JSON and validates it. Malformed JSON is reported against `body`. */
export function parseSubmission(text: string): ValidationResult {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch {
    return { ok: false, fields: [{ field: 'body', message: 'request body must be valid JSON' }] };
  }
  return validateSubmission(parsed);
}

/** Validates an already-parsed body, collecting every offending field. */
export function validateSubmission(parsed: unknown): ValidationResult {
  if (!isPlainObject(parsed)) {
    return { ok: false, fields: [{ field: 'body', message: 'request body must be a JSON object' }] };
  }
  const fields: FieldError[] = [];
  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  if (!hasOwn(parsed, 'input')) {
    fields.push({ field: 'input', message: 'input is required' });
  } else {
    const v = parsed.input;
    if (typeof v !== 'string') {
      fields.push({ field: 'input', message: 'input must be a string' });
    } else if (v.length < 1 || v.length > 1000) {
      fields.push({ field: 'input', message: 'input must be 1 to 1000 characters' });
    } else if (v.trim() === '') {
      fields.push({ field: 'input', message: 'input must not be blank' });
    } else {
      input = v;
    }
  }

  const steps = integerField(parsed, 'steps', DEFAULT_STEPS, 1, 20, fields);
  const failAttempts = integerField(parsed, 'failAttempts', DEFAULT_FAIL_ATTEMPTS, 0, 5, fields);

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

/** Returns a field error when the Idempotency-Key header is present but malformed. */
export function validateIdempotencyKey(raw: string | undefined): FieldError | undefined {
  if (raw === undefined || IDEMPOTENCY_KEY_PATTERN.test(raw)) return undefined;
  return { field: 'Idempotency-Key', message: 'Idempotency-Key must be 1 to 128 characters of A-Z, a-z, 0-9, _ or -' };
}

/** True when the Content-Type media type is application/json, ignoring case and parameters. */
export function isJsonMediaType(header: string | undefined): boolean {
  if (!header) return false;
  return (header.split(';')[0] ?? '').trim().toLowerCase() === 'application/json';
}

/** Canonical payload string (defaults applied, fixed key order) used for idempotency comparison. */
export function normalizePayload(s: JobSubmission): string {
  return JSON.stringify({ input: s.input, steps: s.steps, failAttempts: s.failAttempts });
}

/** Maps an internal row to the exact public representation. */
export function serializeJob(row: JobRow): PublicJob {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.output ?? '' } : null,
    error: row.status === 'failed' ? (row.error ?? '') : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

