import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import type { JobStatus } from './jobs.ts';

/** A job row as stored in SQLite. Never sent to clients directly; see serializeJob. */
export interface JobRow {
  seq: number;
  id: string;
  input: string;
  steps: number;
  fail_attempts: number;
  status: JobStatus;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
  /** Epoch milliseconds before which a queued job must not be claimed (retry delay). */
  available_at: number;
  idem_key: string | null;
  idem_payload: string | null;
}

/** Opens the SQLite database shared by the server and worker processes. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  initSchema(db);
  return db;
}

function initSchema(db: DatabaseSync): void {
  // Both processes may run this at startup; the immediate transaction serializes them.
  transaction(db, () => {
    db.exec(`
      CREATE TABLE IF NOT EXISTS jobs (
        seq INTEGER PRIMARY KEY AUTOINCREMENT,
        id TEXT NOT NULL UNIQUE,
        input TEXT NOT NULL,
        steps INTEGER NOT NULL,
        fail_attempts INTEGER NOT NULL,
        status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
        attempts INTEGER NOT NULL DEFAULT 0,
        completed INTEGER NOT NULL DEFAULT 0,
        output TEXT,
        error TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        available_at INTEGER NOT NULL DEFAULT 0,
        idem_key TEXT UNIQUE,
        idem_payload TEXT
      );
      CREATE INDEX IF NOT EXISTS jobs_claim ON jobs (status, available_at, seq);
      CREATE TABLE IF NOT EXISTS worker_state (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        heartbeat_ms INTEGER NOT NULL
      );
    `);
  });
}

/**
 * Runs `fn` inside a BEGIN IMMEDIATE transaction. The callback must be synchronous: no transaction
 * may stay open across an await.
 */
export function transaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // the transaction was never started or is already closed
    }
    throw e;
  }
  return result;
}

function one(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): JobRow | undefined {
  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
}

function many(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): JobRow[] {
  return db.prepare(sql).all(...params) as unknown as JobRow[];
}

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return one(db, 'SELECT * FROM jobs WHERE id = ?', id);
}

export function listJobRows(db: DatabaseSync): JobRow[] {
  return many(db, 'SELECT * FROM jobs ORDER BY seq DESC');
}

export interface NewJob {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  now: string;
  idemKey: string | null;
  idemPayload: string | null;
}

export type CreateOutcome =
  | { kind: 'created'; job: JobRow }
  | { kind: 'replayed'; job: JobRow }
  | { kind: 'conflict' };

/**
 * Creates a job, or resolves an idempotency key, in one immediate transaction. The returned row is
 * read inside the transaction, so it reflects the state at creation (queued), even if a worker
 * claims the job immediately afterwards.
 */
export function createJobTx(db: DatabaseSync, job: NewJob): CreateOutcome {
  return transaction<CreateOutcome>(db, () => {
    if (job.idemKey !== null) {
      const existing = one(db, 'SELECT * FROM jobs WHERE idem_key = ?', job.idemKey);
      if (existing) {
        return existing.idem_payload === job.idemPayload ? { kind: 'replayed', job: existing } : { kind: 'conflict' };
      }
    }
    db.prepare(
      `INSERT INTO jobs (id, input, steps, fail_attempts, status, attempts, completed, output, error,
                         created_at, updated_at, available_at, idem_key, idem_payload)
       VALUES (?, ?, ?, ?, 'queued', 0, 0, NULL, NULL, ?, ?, 0, ?, ?)`,
    ).run(job.id, job.input, job.steps, job.failAttempts, job.now, job.now, job.idemKey, job.idemPayload);
    const row = getJobRow(db, job.id);
    if (!row) throw new Error('inserted job not found');
    return { kind: 'created', job: row };
  });
}

// ---- Health -------------------------------------------------------------------------------------

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  db.prepare(
    `INSERT INTO worker_state (id, heartbeat_ms) VALUES (1, ?)
     ON CONFLICT(id) DO UPDATE SET heartbeat_ms = excluded.heartbeat_ms`,
  ).run(nowMs);
}

export function readHeartbeat(db: DatabaseSync): number | undefined {
  const row = db.prepare('SELECT heartbeat_ms AS hb FROM worker_state WHERE id = 1').get() as { hb: number } | undefined;
  return row?.hb;
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM worker_state WHERE id = 1').run();
}

// ---- Worker queries -----------------------------------------------------------------------------

/**
 * Returns the oldest job left in `running` (an attempt interrupted by a crash or shutdown). Its
 * progress is reset and it is returned with its existing attempt number, so the replay does not
 * consume another attempt from the retry budget.
 */
export function recoverRunning(db: DatabaseSync, nowIso: string): { id: string; attempts: number } | undefined {
  return transaction(db, () => {
    const row = one(db, "SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1");
    if (!row) return undefined;
    db.prepare("UPDATE jobs SET completed = 0, updated_at = ? WHERE id = ? AND status = 'running'").run(nowIso, row.id);
    return { id: row.id, attempts: row.attempts };
  });
}

/** Claims the oldest queued job whose retry delay has elapsed, starting a new attempt. */
export function claimNext(db: DatabaseSync, nowMs: number, nowIso: string): { id: string; attempts: number } | undefined {
  return transaction(db, () => {
    const row = one(db, "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1", nowMs);
    if (!row) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, output = NULL, error = NULL,
                       updated_at = ? WHERE id = ?`,
    ).run(nowIso, row.id);
    return { id: row.id, attempts: row.attempts + 1 };
  });
}

export function recordProgress(db: DatabaseSync, id: string, completed: number, nowIso: string): void {
  transaction(db, () => {
    db.prepare("UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(completed, nowIso, id);
  });
}

export function completeJob(db: DatabaseSync, id: string, total: number, output: string, nowIso: string): void {
  transaction(db, () => {
    db.prepare(
      "UPDATE jobs SET status = 'completed', completed = ?, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
    ).run(total, output, nowIso, id);
  });
}

/** Ends a transient failure: re-queues the job after a delay, or fails it terminally. */
export function recordTransientFailure(
  db: DatabaseSync,
  id: string,
  terminal: boolean,
  retryAtMs: number,
  nowIso: string,
): void {
  transaction(db, () => {
    if (terminal) {
      db.prepare(
        "UPDATE jobs SET status = 'failed', completed = 0, output = NULL, error = 'transient failure', updated_at = ? WHERE id = ? AND status = 'running'",
      ).run(nowIso, id);
    } else {
      db.prepare(
        "UPDATE jobs SET status = 'queued', completed = 0, output = NULL, error = NULL, available_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
      ).run(retryAtMs, nowIso, id);
    }
  });
}

