import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { createJobTx, getJobRow, listJobRows, openDatabase, readHeartbeat } from './db.ts';
import {
  isJsonMediaType,
  normalizePayload,
  parseSubmission,
  serializeJob,
  validateIdempotencyKey,
  type FieldError,
} from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** A worker heartbeat older than this means the worker is down. */
const WORKER_LIVENESS_MS = 3000;
/** Upper bound on the bytes read from a submission body. Valid bodies are far smaller. */
const MAX_BODY_BYTES = 64 * 1024;
/** How long shutdown waits for active requests before dropping the remaining connections. */
const SHUTDOWN_GRACE_MS = 5000;

function sendJson(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  sendJson(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawKey = req.headers['idempotency-key'];
  const keyError = validateIdempotencyKey(rawKey);
  // The body is always read so that the response is well-formed even when the request is rejected.
  const { text, tooLarge } = await readBody(req);

  const problems: FieldError[] = [];
  if (keyError) problems.push(keyError);
  let submission: ReturnType<typeof parseSubmission> | undefined;
  if (!isJsonMediaType(req.headers['content-type'])) {
    problems.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (tooLarge) {
    problems.push({ field: 'body', message: `request body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    submission = parseSubmission(text);
    if (!submission.ok) problems.push(...submission.fields);
  }

  if (problems.length > 0 || !submission || !submission.ok) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', problems);
    return;
  }

  const value = submission.value;
  const outcome = createJobTx(db, {
    id: randomUUID(),
    input: value.input,
    steps: value.steps,
    failAttempts: value.failAttempts,
    now: new Date().toISOString(),
    idemKey: rawKey ?? null,
    idemPayload: rawKey === undefined ? null : normalizePayload(value),
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, serializeJob(outcome.job));
}

function workerIsUp(): boolean {
  const heartbeat = readHeartbeat(db);
  return heartbeat !== undefined && Date.now() - heartbeat <= WORKER_LIVENESS_MS;
}

const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const jobMatch = JOB_PATH.exec(pathname);

  let allowed: string[];
  if (pathname === '/') allowed = ['GET'];
