import { createJobTx, getJobRow, listJobRows, openDatabase, readHeartbeat } from './db.ts';
import {
  isJsonMediaType,
  normalizePayload,
  parseSubmission,
  serializeJob,
  validateIdempotencyKey,
  type FieldError,
} from './jobs.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** A worker heartbeat older than this means the worker is down. */
const WORKER_LIVENESS_MS = 3000;
/** Upper bound on the bytes read from a submission body. Valid bodies are far smaller. */
const MAX_BODY_BYTES = 64 * 1024;
/** How long shutdown waits for active requests before dropping the remaining connections. */
const SHUTDOWN_GRACE_MS = 5000;

function sendJson(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
  res.end(JSON.stringify(body));
}

