import { setInterval as every, setTimeout as sleep } from 'node:timers/promises';
import {
  claimNext,
  clearHeartbeat,
  completeJob,
  getJobRow,
  openDatabase,
  recordProgress,
  recordTransientFailure,
  recoverRunning,
  writeHeartbeat,
} from './db.ts';

/** Time to process one step. */
const STEP_MS = 100;
/** Idle poll interval for new work. */
const POLL_MS = 100;
/** Heartbeat interval. The server reports the worker "down" after 3 s without one. */
const HEARTBEAT_MS = 500;
/** Delay before a transiently failed attempt is retried. Must be within 250 ms to 2 s. */
const RETRY_DELAY_MS = 500;
/** Total attempts allowed, including the first. */
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function beat(): void {
  try {
    writeHeartbeat(db, Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}

/**
 * Processes one attempt of a job, step by step. Each step's progress is committed before the next
 * begins. On a shutdown request the attempt stops at a step boundary and its row is left in
 * `running`, which the next worker start recovers.
 */
async function runAttempt(id: string, attemptNo: number): Promise<void> {
  const job = getJobRow(db, id);
  if (!job) return;

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;

    // Transient failures are decided after the first step's delay, before any progress is recorded.
    if (step === 1 && attemptNo <= job.fail_attempts) {
      const terminal = attemptNo >= MAX_ATTEMPTS;
      recordTransientFailure(db, id, terminal, Date.now() + RETRY_DELAY_MS, new Date().toISOString());
      if (!terminal) console.log(`job ${id}: attempt ${attemptNo} failed transiently; retrying`);
      else console.log(`job ${id}: failed after ${attemptNo} attempts`);
      return;
    }

    const nowIso = new Date().toISOString();
    if (step === job.steps) {
      completeJob(db, id, job.steps, job.input.toUpperCase(), nowIso);
      console.log(`job ${id}: completed`);
    } else {
      recordProgress(db, id, step, nowIso);
    }
  }
}

async function main(): Promise<void> {
  beat();
  const heartbeatTimer = (async () => {
    for await (const _ of every(HEARTBEAT_MS)) {
      if (stopping) break;
      beat();
    }
  })();

  console.log('worker started');
  while (!stopping) {
    // Jobs left in `running` by an earlier process are recovered before ordinary queued work.
    // Recovery keeps the attempt number that was already counted when the attempt was claimed:
    // a crash must not consume transient retry budget.
    const next = recoverRunning(db, new Date().toISOString()) ?? claimNext(db, Date.now(), new Date().toISOString());
    if (!next) {
      await sleep(POLL_MS);
      continue;
    }
    await runAttempt(next.id, next.attempts);
  }

  await heartbeatTimer;
  clearHeartbeat(db);
  db.close();
  console.log('worker stopped');
}

main().catch((err: unknown) => {
  console.error('worker failed:', err);
  process.exitCode = 1;
});

