  // The body is always read so that the response is well-formed even when the request is rejected.
  const { text, tooLarge } = await readBody(req);

  const problems: FieldError[] = [];
  if (keyError) problems.push(keyError);
  let value: JobSubmission | undefined;
  if (!isJsonMediaType(req.headers['content-type'])) {
    problems.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (tooLarge) {
    problems.push({ field: 'body', message: `request body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    const parsed = parseSubmission(text);
    if (parsed.ok) value = parsed.value;
    else problems.push(...parsed.fields);
  }

  if (problems.length > 0 || value === undefined) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', problems);
    return;
  }

  const outcome = createJobTx(db, {
    id: randomUUID(),
    input: value.input,
    steps: value.steps,
    failAttempts: value.failAttempts,
    now: new Date().toISOString(),
    idemKey: rawKey ?? null,
    idemPayload: rawKey === undefined ? null : normalizePayload(value),
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, serializeJob(outcome.job));
}

function workerIsUp(): boolean {
  const heartbeat = readHeartbeat(db);
  return heartbeat !== undefined && Date.now() - heartbeat <= WORKER_LIVENESS_MS;
}

const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const jobMatch = JOB_PATH.exec(pathname);

  let allowed: string[];
  if (pathname === '/') allowed = ['GET'];
  else if (pathname === '/health') allowed = ['GET'];
  else if (pathname === '/api/jobs') allowed = ['GET', 'POST'];
  else if (jobMatch) allowed = ['GET'];
  else {
    sendError(res, 404, 'not_found', 'No such route.');
    return;
  }
  if (!allowed.includes(method)) {
    res.writeHead(405, { 'content-type': 'application/json; charset=utf-8', allow: allowed.join(', ') });
    res.end(JSON.stringify({ error: { code: 'method_not_allowed', message: `${method} is not allowed on this route.` } }));
    return;
  }

  if (pathname === '/') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    sendJson(res, 200, { status: 'ok', worker: workerIsUp() ? 'up' : 'down' });
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') {
      await createJob(req, res);
      return;
    }
    sendJson(res, 200, { jobs: listJobRows(db).map(serializeJob) });
    return;
  }
  // Only the job route remains, and it is GET-only.
  let id: string;
  try {
    id = decodeURIComponent(jobMatch![1]!);
  } catch {
    sendError(res, 404, 'not_found', 'No such job.');
    return;
  }
  const row = getJobRow(db, id);
  if (!row) {
    sendError(res, 404, 'not_found', 'No such job.');
    return;
  }
  sendJson(res, 200, serializeJob(row));
}

const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (res.headersSent) {
      res.end();
    } else {
      sendError(res, 500, 'internal_error', 'Internal server error.');
    }
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  // Stop accepting connections, close idle keep-alive sockets, and let active handlers finish.
  server.close(() => {
    db.close();
    console.log('server stopped');
  });
  server.closeIdleConnections();
  const force = setTimeout(() => server.closeAllConnections(), SHUTDOWN_GRACE_MS);
  force.unref();
}

for (const signal of ['SIGTERM', 'SIGINT'] as const) {
  process.on(signal, shutdown);
}

