// Scenario tests for the job tracker. Run from outside the repo; the app is started from the repo's dist/.
import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const REPO = process.env.REPO;
const base = mkdtempSync(join(process.env.TMPDIR ?? tmpdir(), 'jt-'));
const DB = join(base, 'nested', 'dir', 'jobs.db');
const PORT = 3917;
const URL_ = `http://127.0.0.1:${PORT}`;
let failures = 0;
const ok = (cond, msg) => {
  if (!cond) failures++;
  console.log(`${cond ? 'PASS' : 'FAIL'} ${msg}`);
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const procs = {};
function start(name) {
  const child = spawn('node', ['--disable-warning=ExperimentalWarning', `dist/${name}.js`], {
    cwd: REPO,
    env: { ...process.env, PORT: String(PORT), DATABASE_PATH: DB },
    stdio: ['ignore', 'inherit', 'inherit'],
  });
  procs[name] = child;
  return child;
}
function kill(name, sig = 'SIGTERM') {
  return new Promise((r) => {
    const c = procs[name];
    if (!c || c.exitCode !== null || c.signalCode !== null) return r();
    c.once('exit', r);
    c.kill(sig);
  });
}

async function req(method, path, { body, headers = {}, raw } = {}) {
  const init = { method, headers: { ...headers } };
  if (raw !== undefined) init.body = raw;
  else if (body !== undefined) {
    init.body = JSON.stringify(body);
    if (!init.headers['content-type']) init.headers['content-type'] = 'application/json';
  }
  const res = await fetch(URL_ + path, init);
  const text = await res.text();
  let json;
  try {
    json = JSON.parse(text);
  } catch {}
  return { status: res.status, ct: res.headers.get('content-type'), text, json };
}

async function waitUntil(fn, timeoutMs, label) {
  const end = Date.now() + timeoutMs;
  for (;;) {
    const v = await fn().catch(() => undefined);
    if (v) return v;
    if (Date.now() > end) throw new Error(`timeout: ${label}`);
    await sleep(25);
  }
}
const getJob = async (id) => (await req('GET', `/api/jobs/${id}`)).json;
const finished = (id, ms = 20000) =>
  waitUntil(async () => {
    const j = await getJob(id);
    return j.status === 'completed' || j.status === 'failed' ? j : undefined;
  }, ms, `finish ${id}`);

async function main() {
  // Worker first, then server: both must work in either order.
  start('worker');
  await sleep(300);
  start('server');
  const up = await waitUntil(async () => {
    const r = await req('GET', '/health');
    return r.json?.worker === 'up' ? r : undefined;
  }, 10000, 'health worker up');
  ok(up.status === 200 && up.ct.startsWith('application/json'), 'health 200 JSON with worker up');

  // ---- validation -----------------------------------------------------------------------------
  const before = (await req('GET', '/api/jobs')).json.jobs.length;
  const bad = [
    [{ raw: '{bad json', headers: { 'content-type': 'application/json' } }, 'body'],
    [{ raw: '[]', headers: { 'content-type': 'application/json' } }, 'body'],
    [{ raw: 'null', headers: { 'content-type': 'application/json' } }, 'body'],
    [{ raw: '{"input":"x"}', headers: { 'content-type': 'text/plain' } }, 'body'],
    [{ raw: '{"input":"x"}' }, 'body'],
    [{ body: { input: '   ' } }, 'input'],
    [{ body: { input: '' } }, 'input'],
    [{ body: { input: 'a'.repeat(1001) } }, 'input'],
    [{ body: { input: 5 } }, 'input'],
    [{ body: { input: 'x', steps: '3' } }, 'steps'],
    [{ body: { input: 'x', steps: 2.5 } }, 'steps'],
    [{ body: { input: 'x', steps: 0 } }, 'steps'],
    [{ body: { input: 'x', steps: 21 } }, 'steps'],
    [{ body: { input: 'x', steps: null } }, 'steps'],
    [{ body: { input: 'x', failAttempts: 6 } }, 'failAttempts'],
    [{ body: { input: 'x', failAttempts: -1 } }, 'failAttempts'],
    [{ body: { input: 'x', extra: 1 } }, 'extra'],
    [{ body: { steps: 3 } }, 'input'],
    [{ body: { input: 'x' }, headers: { 'idempotency-key': 'bad key!' } }, 'Idempotency-Key'],
    [{ body: { input: 'x' }, headers: { 'idempotency-key': '' } }, 'Idempotency-Key'],
  ];
  for (const [opts, field] of bad) {
    const r = await req('POST', '/api/jobs', opts);
    const fields = r.json?.error?.fields?.map((f) => f.field) ?? [];
    ok(r.status === 400 && r.json?.error?.code === 'invalid_request' && fields.includes(field), `reject ${field} (${r.status}) ${JSON.stringify(opts).slice(0, 80)}`);
  }
  const multi = await req('POST', '/api/jobs', { body: { input: ' ', steps: 99, extra: true } });
  ok(multi.json?.error?.fields?.length === 3, `multiple field errors combined (${multi.json?.error?.fields?.length})`);
  const boundary = await req('POST', '/api/jobs', { body: { input: 'a'.repeat(1000), steps: 1 } });
  ok(boundary.status === 201, '1000-char input accepted');
  const afterBad = (await req('GET', '/api/jobs')).json.jobs.length;
  ok(afterBad === before + 1, `only valid submissions created jobs (${before} -> ${afterBad})`);

  // ---- routing --------------------------------------------------------------------------------
  const nf = await req('GET', '/nope');
  ok(nf.status === 404 && nf.json?.error?.code === 'not_found' && nf.ct.startsWith('application/json'), 'unknown path 404 JSON');
  const extra = await req('GET', '/api/jobs/abc/def');
  ok(extra.status === 404, 'extra path segment 404');
  const missing = await req('GET', '/api/jobs/does-not-exist');
  ok(missing.status === 404 && missing.json?.error?.code === 'not_found', 'missing job 404');
  const m405 = await req('DELETE', '/api/jobs');
  ok(m405.status === 405 && m405.json?.error?.code === 'method_not_allowed', 'wrong method 405');
  const m405b = await req('POST', '/health');
  ok(m405b.status === 405, 'POST /health 405');
  const page = await req('GET', '/');
  ok(page.status === 200 && page.ct.startsWith('text/html') && page.text.includes('data-testid="job-form"'), 'GET / serves UI');

  // ---- representation & ordering ---------------------------------------------------------------
  const first = await req('POST', '/api/jobs', { body: { input: 'first', steps: 2 } });
  const second = await req('POST', '/api/jobs', { body: { input: 'second', steps: 2 } });
  ok(first.status === 201 && first.json.status === 'queued' && first.json.progress.total === 2, 'created job representation');
  const keys = Object.keys(first.json).sort().join(',');
  ok(keys === 'attempts,createdAt,error,failAttempts,id,input,progress,result,status,steps,updatedAt', `exact public fields (${keys})`);
  ok(first.json.failAttempts === 0 && first.json.steps === 2, 'steps/failAttempts echo');
  const list = (await req('GET', '/api/jobs')).json.jobs;
  ok(list[0].id === second.json.id || list.findIndex((j) => j.id === second.json.id) < list.findIndex((j) => j.id === first.json.id), 'list newest first');

  // ---- processing -----------------------------------------------------------------------------
  const big = await req('POST', '/api/jobs', { body: { input: 'héllo ß 😀 straße', steps: 20 } });
  const seen = new Set();
  let sawRunning = false;
  const t0 = Date.now();
  await waitUntil(async () => {
    const j = await getJob(big.json.id);
    if (j.status === 'running') sawRunning = true;
    seen.add(j.progress.completed);
    return j.status === 'completed' ? j : undefined;
  }, 20000, 'big job');
  const bigDone = await getJob(big.json.id);
  ok(sawRunning, 'running state observed');
  ok(seen.size > 5, `incremental progress observed (${seen.size} distinct values)`);
  ok(bigDone.result.output === 'HÉLLO SS 😀 STRASSE'.replace('SS', 'SS') || bigDone.result.output === 'héllo ß 😀 straße'.toUpperCase(), `uppercase output (${bigDone.result.output})`);
  ok(bigDone.progress.completed === 20 && bigDone.attempts === 1 && bigDone.attempts === 1, 'completed progress and attempts');
  ok(Date.now() - t0 < 10000, 'large job processed in time');

  const f = await finished(first.json.id);
  ok(f.status === 'completed' && f.result.output === 'FIRST' && f.error === null, 'small job completes');
  const pickupStart = Date.now();
  const p = await req('POST', '/api/jobs', { body: { input: 'pick', steps: 1 } });
  await finished(p.json.id);
  ok(Date.now() - pickupStart < 2000, 'idle pickup fast');

  // ---- retries --------------------------------------------------------------------------------
  const r0 = (await req('POST', '/api/jobs', { body: { input: 'r0', steps: 2, failAttempts: 0 } })).json;
  const r2 = (await req('POST', '/api/jobs', { body: { input: 'r2', steps: 2, failAttempts: 2 } })).json;
  const r3 = (await req('POST', '/api/jobs', { body: { input: 'r3', steps: 2, failAttempts: 3 } })).json;
  const r5 = (await req('POST', '/api/jobs', { body: { input: 'r5', steps: 2, failAttempts: 5 } })).json;
  const d0 = await finished(r0.id);
  ok(d0.status === 'completed' && d0.attempts === 1, 'failAttempts 0 completes on attempt 1');
  const d2 = await finished(r2.id);
  ok(d2.status === 'completed' && d2.attempts === 3 && d2.result.output === 'R2', `failAttempts 2 completes on attempt 3 (${d2.attempts})`);
  const d3 = await finished(r3.id);
  ok(d3.status === 'failed' && d3.attempts === 3 && d3.error === 'transient failure' && d3.result === null && d3.progress.completed === 0, 'failAttempts 3 fails after 3 attempts');
  const d5 = await finished(r5.id);
  ok(d5.status === 'failed' && d5.attempts === 3, 'failAttempts 5 fails after 3 attempts');

  // ---- idempotency ----------------------------------------------------------------------------
  const k1 = await req('POST', '/api/jobs', { body: { input: 'idem' }, headers: { 'idempotency-key': 'key-A' } });
  const k2 = await req('POST', '/api/jobs', { body: { input: 'idem', steps: 5, failAttempts: 0 }, headers: { 'idempotency-key': 'key-A' } });
  ok(k1.status === 201 && k2.status === 200 && k1.json.id === k2.json.id, 'same key + defaults-equal payload replays 200');
  const k3 = await req('POST', '/api/jobs', { body: { input: 'idem', steps: 6 }, headers: { 'idempotency-key': 'key-A' } });
  ok(k3.status === 409 && k3.json.error.code === 'idempotency_conflict', 'same key different payload 409');
  const con = await Promise.all(Array.from({ length: 8 }, () => req('POST', '/api/jobs', { body: { input: 'race' }, headers: { 'idempotency-key': 'key-race' } })));
  const created = con.filter((r) => r.status === 201).length;
  const replayed = con.filter((r) => r.status === 200).length;
  ok(created === 1 && replayed === 7, `concurrent same key: 1 created, 7 replayed (${created}/${replayed})`);
  const u1 = await req('POST', '/api/jobs', { body: { input: 'same' } });
  const u2 = await req('POST', '/api/jobs', { body: { input: 'same' } });
  ok(u1.status === 201 && u2.status === 201 && u1.json.id !== u2.json.id, 'unkeyed identical submissions create separate jobs');

  // ---- crash recovery: worker SIGKILL during a long job ---------------------------------------
  const longJob = await req('POST', '/api/jobs', { body: { input: 'crash test', steps: 20, failAttempts: 2 }, headers: { 'idempotency-key': 'crash-1' } });
  await waitUntil(async () => (await getJob(longJob.json.id)).attempts === 3, 15000, 'reach attempt 3');
  await waitUntil(async () => (await getJob(longJob.json.id)).progress.completed >= 3, 5000, 'progress on attempt 3');
  await kill('worker', 'SIGKILL');
  await sleep(3500);
  const down = await req('GET', '/health');
  ok(down.json?.worker === 'down', 'health worker down after SIGKILL and heartbeat expiry');
  start('worker');
  const recovered = await finished(longJob.json.id, 15000);
  ok(recovered.status === 'completed' && recovered.attempts === 3 && recovered.result.output === 'CRASH TEST', `recovers attempt 3 after crash (attempts=${recovered.attempts}, ${recovered.status})`);

  // ---- durability: SIGTERM both, restart, idempotency and terminal state survive --------------
  const terminalBefore = await getJob(d3.id);
  await kill('server', 'SIGTERM');
  await kill('worker', 'SIGTERM');
  ok(procs.server.exitCode === 0 && procs.worker.exitCode === 0, `clean SIGTERM exit (server ${procs.server.exitCode}, worker ${procs.worker.exitCode})`);
  start('server');
  start('worker');
  await waitUntil(async () => (await req('GET', '/health')).json?.worker === 'up', 10000, 'restart up');
  const terminalAfter = await getJob(d3.id);
  ok(JSON.stringify(terminalBefore) === JSON.stringify(terminalAfter), 'terminal job unchanged across restart');
  const replay = await req('POST', '/api/jobs', { body: { input: 'idem' }, headers: { 'idempotency-key': 'key-A' } });
  ok(replay.status === 200 && replay.json.id === k1.json.id, 'idempotency mapping survives restart');
  const replayCrash = await req('POST', '/api/jobs', { body: { input: 'crash test', steps: 20, failAttempts: 2 }, headers: { 'idempotency-key': 'crash-1' } });
  ok(replayCrash.status === 200 && replayCrash.json.id === longJob.json.id, 'idempotency mapping for completed job survives');

  // Queued/running job across SIGKILL of the server only.
  const pend = await req('POST', '/api/jobs', { body: { input: 'pending', steps: 3 } });
  await kill('server', 'SIGKILL');
  start('server');
  await waitUntil(async () => (await req('GET', '/health')).status === 200, 10000, 'server back');
  const pendDone = await finished(pend.json.id);
  ok(pendDone.status === 'completed', 'job survives server SIGKILL and completes');

  // Shutdown during a long request-free run: worker stops promptly.
  const sT = Date.now();
  await kill('worker', 'SIGTERM');
  ok(Date.now() - sT < 2000, `worker SIGTERM shutdown prompt (${Date.now() - sT} ms)`);

  for (const n of ['server', 'worker']) await kill(n, 'SIGKILL');
  console.log(failures === 0 ? 'ALL PASSED' : `${failures} FAILURE(S)`);
  process.exit(failures === 0 ? 0 : 1);
}

main().catch(async (e) => {
  console.error('ERROR', e);
  for (const n of ['server', 'worker']) await kill(n, 'SIGKILL');
  process.exit(2);
});

