// Scenario tests for the job tracker. Run from outside the repo; the app is started from the repo's dist/.
import { spawn } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';

const REPO = process.env.REPO;
const base = mkdtempSync(join(process.env.TMPDIR ?? tmpdir(), 'jt-'));
const DB = join(base, 'nested', 'dir', 'jobs.db');
const PORT = 3917;
const URL_ = `http://127.0.0.1:${PORT}`;
